import{_ as e,o as a,c as i,ag as o}from"./chunks/framework.C9sp7nFj.js";const u=JSON.parse('{"title":"SetPositioner 设置变位机坐标系","description":"","frontmatter":{},"headers":[],"relativePath":"3. 指令/5. 设置指令/SetPositioner.md","filePath":"3. 指令/5. 设置指令/SetPositioner.md","lastUpdated":1778862643000}'),r={name:"3. 指令/5. 设置指令/SetPositioner.md"};function s(n,t,d,l,h,p){return a(),i("div",null,[...t[0]||(t[0]=[o('<h1 id="setpositioner-设置变位机坐标系" tabindex="-1">SetPositioner 设置变位机坐标系 <a class="header-anchor" href="#setpositioner-设置变位机坐标系" aria-label="Permalink to &quot;SetPositioner 设置变位机坐标系&quot;">​</a></h1><p>该指令用于<strong>设置并切换机器人的参考坐标系为特定的变位机坐标系（Positioner Coordinate System）</strong>。执行此指令后，机器人的所有运动指令将以变位机的中心或旋转轴作为参考基准，实现机器人与变位机的联动控制。</p><h2 id="指令格式" tabindex="-1">指令格式 <a class="header-anchor" href="#指令格式" aria-label="Permalink to &quot;指令格式&quot;">​</a></h2><p>SetPositioner(Positioner) SetPositioner(变位机参数)</p><hr><h2 id="参数详细说明" tabindex="-1">参数详细说明 <a class="header-anchor" href="#参数详细说明" aria-label="Permalink to &quot;参数详细说明&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>说明</th><th>默认值/备注</th></tr></thead><tbody><tr><td>Positioner：变位机参数（Positioner Param）</td><td>POSITIONER 变量</td><td>指定当前需要启用的变位机坐标系。该变量包含变位机相对于机器人基坐标系的位置关系，以及变位机自身的轴参数和旋转逻辑。</td><td></td></tr></tbody></table><hr><h2 id="工作原理" tabindex="-1">工作原理 <a class="header-anchor" href="#工作原理" aria-label="Permalink to &quot;工作原理&quot;">​</a></h2><p>执行指令后，系统将参考基准从基坐标系切换至变位机坐标系。这意味着，即使变位机在旋转运动，机器人也能通过实时坐标变换，保持与变位机上工件的相对位置和轨迹恒定。</p><hr><h2 id="示例" tabindex="-1">示例： <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例：&quot;">​</a></h2><div class="language-estun vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">estun</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">SetPositioner</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(POSITIONER0)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><strong>执行结果：</strong></p><p>选择 <strong>POSITIONER0</strong> 作为当前的运动参考基准，后续的运动指令（如 <code>MovL</code>）将相对于该变位机进行位置解析。</p><hr><h2 id="应用场景" tabindex="-1">应用场景 <a class="header-anchor" href="#应用场景" aria-label="Permalink to &quot;应用场景&quot;">​</a></h2><ul><li><strong>焊接协同</strong>：在大型工件焊接时，变位机带动工件旋转，机器人同步跟踪焊缝，确保焊接速度与角度的一致性。</li><li><strong>环绕加工</strong>：在圆形或球形物体表面进行涂胶或切割时，利用变位机轴简化编程轨迹。</li><li><strong>多工位柔性生产</strong>：在包含旋转工作台的单元中，通过切换变位机参数快速定位不同面的加工区域。</li></ul>',18)])])}const P=e(r,[["render",s]]);export{u as __pageData,P as default};
